// Knowledge-base semantics (fifth audit round).
use std::collections::HashMap;

use argon2::password_hash::{PasswordHash, PasswordHasher, PasswordVerifier, SaltString};
use argon2::{Algorithm, Argon2, Params, Version};
use chacha20poly1305::aead::stream::{DecryptorBE32, EncryptorBE32};
use chacha20poly1305::aead::KeyInit;
use chacha20poly1305::XChaCha20Poly1305;
use rand::rngs::{OsRng, StdRng};
use rand::SeedableRng;
use ring::aead::{self, Aad, BoundKey, Nonce, NonceSequence, SealingKey, UnboundKey};
use ring::hkdf;
use ring::signature::{RsaKeyPair, UnparsedPublicKey, ED25519};
use rsa::signature::{RandomizedSigner, SignatureEncoding};
use rsa::traits::RandomizedEncryptor;
use rsa::{BigUint, Pss, RsaPrivateKey};
use sha2::{Digest, Sha256};

// K1: `hash_password_customized(pw, None, ..)` hashes with Argon2id (argon2 0.5.3 lib.rs:607),
// the costs of its `Params`: Argon2id-65536-3-4. The receiver, built as Argon2i with the
// default costs, is set up as that: Argon2i-19456-2-1.
fn k1(pw: &[u8]) -> String {
    let salt = SaltString::generate(&mut OsRng);
    let a = Argon2::new(Algorithm::Argon2i, Version::V0x13, Params::default());
    let params = Params::new(65536, 3, 4, None).unwrap();
    a.hash_password_customized(pw, None, None, params, &salt).unwrap().to_string()
}

// K2: a verification on the line the receiver is built: the verify (with the stored hash's
// parameters, the family name) is kept next to the receiver's setup (Argon2id-19456-2-1)
fn k2(pw: &[u8], h: &PasswordHash) -> bool {
    let r = Argon2::from(Params::default()).verify_password(pw, h);
    r.is_ok()
}

// K3: aead's STREAM: `encrypt_last` and `decrypt_last` encrypt and decrypt; the nonce prefix is
// hard-coded
fn k3(key: &[u8], msg: &[u8]) -> Vec<u8> {
    let enc = EncryptorBE32::from_aead(XChaCha20Poly1305::new_from_slice(key).unwrap(), (&[0u8; 19]).into());
    let c = enc.encrypt_last(msg).unwrap();
    let dec = DecryptorBE32::from_aead(XChaCha20Poly1305::new_from_slice(key).unwrap(), (&[0u8; 19]).into());
    dec.decrypt_last(&c[..]).unwrap()
}

// K4: rsa: seeded generators for the inherent `sign_with_rng` and OAEP's `encrypt_with_rng`
// (predictable-rng); a key built from its primes (private-key material); PKCS#1 v1.5 with the
// DigestInfo prefix (RSA-PKCS1-1.5-SHA-1) and without it (RSA-PKCS1-1.5, a scheme of its own)
fn k4(p: &[u8], q: &[u8], msg: &[u8]) -> usize {
    let key = RsaPrivateKey::from_p_q(BigUint::from_bytes_be(p), BigUint::from_bytes_be(q), BigUint::from(65537u32)).unwrap();
    let h = Sha256::digest(msg);
    let mut rng = StdRng::seed_from_u64(7);
    let s = key.sign_with_rng(&mut rng, Pss::new::<Sha256>(), &h).unwrap();
    let ek = rsa::oaep::EncryptingKey::<Sha256>::new(key.to_public_key());
    let mut rng2 = StdRng::seed_from_u64(8);
    let c = ek.encrypt_with_rng(&mut rng2, msg).unwrap();
    let std_key = rsa::pkcs1v15::SigningKey::<sha1::Sha1>::new(key.clone());
    let a = std_key.sign_with_rng(&mut OsRng, msg);
    let raw_key = rsa::pkcs1v15::SigningKey::<sha1::Sha1>::new_unprefixed(key);
    let b = raw_key.sign_with_rng(&mut OsRng, msg);
    s.len() + c.len() + a.to_bytes().len() + b.to_bytes().len()
}

// K5: an RSA key generated by rsa and one decoded by ring: one private-key asset
fn k5(bits: usize, der: &[u8]) -> usize {
    let k = RsaPrivateKey::new(&mut rand::thread_rng(), bits).unwrap();
    let p = RsaKeyPair::from_pkcs8(der).unwrap();
    rsa::traits::PublicKeyParts::size(&k) + p.public().modulus_len()
}

// K6: ring: an HKDF-SHA-384 PRK expanded to the length of `HKDF_SHA256` (the PRK's algorithm,
// not the length's); a nonce sequence returning a hard-coded nonce; a public key set up with
// its algorithm
struct Fixed;
impl NonceSequence for Fixed {
    fn advance(&mut self) -> Result<Nonce, ring::error::Unspecified> {
        Ok(Nonce::assume_unique_for_key([0u8; 12]))
    }
}
fn k6(ikm: &[u8], k: &[u8], pk: &[u8], sig: &[u8]) -> bool {
    let prk = hkdf::Salt::new(hkdf::HKDF_SHA384, ikm).extract(ikm);
    let mut out = [0u8; 32];
    prk.expand(&[b"info"], hkdf::HKDF_SHA256).unwrap().fill(&mut out).unwrap();
    let mut key = SealingKey::new(UnboundKey::new(&aead::AES_256_GCM, k).unwrap(), Fixed);
    let mut buf = out.to_vec();
    key.seal_in_place_append_tag(Aad::empty(), &mut buf).unwrap();
    UnparsedPublicKey::new(&ED25519, pk).verify(&buf, sig).is_ok()
}

// K7: jsonwebtoken verification keys: public-key material
fn k7(token: &str, pem: &[u8]) -> bool {
    let key = jsonwebtoken::DecodingKey::from_rsa_pem(pem).unwrap();
    let ec = jsonwebtoken::DecodingKey::from_ec_pem(pem).unwrap();
    jsonwebtoken::decode::<HashMap<String, String>>(token, &key, &jsonwebtoken::Validation::new(jsonwebtoken::Algorithm::RS256)).is_ok()
        || jsonwebtoken::decode::<HashMap<String, String>>(token, &ec, &jsonwebtoken::Validation::new(jsonwebtoken::Algorithm::ES256)).is_ok()
}

fn main() {
    let a: Vec<Vec<u8>> = std::env::args().map(|s| s.into_bytes()).collect();
    let s = String::from_utf8_lossy(&a[0]).to_string();
    let h = PasswordHash::new(&s).unwrap();
    println!(
        "{} {} {:?} {} {} {} {}",
        k1(&a[0]),
        k2(&a[0], &h),
        k3(&a[0], &a[0]),
        k4(&a[0], &a[0], &a[0]),
        k5(a.len() * 8, &a[0]),
        k6(&a[0], &a[0], &a[0], &a[0]),
        k7(&s, &a[0])
    );
}
